$disk=Storage::disk('public');$disk->makeDirectory('product-videos');$source='product-videos/compression-fixture.mp4';$target=$disk->path($source);
(new Process(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-y','-f','lavfi','-i','testsrc2=size=1920x1080:rate=24','-t','1','-c:v','libx264','-preset','ultrafast','-crf','18',$target]))->setTimeout(30)->mustRun();
$result=ProductVideos::optimize($source);ok($result!==$source,'HD product source is compressed');ok($disk->size($result)<$disk->size($source),'Compressed product video is smaller');$probe=new Process(['ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=codec_name,width,height','-of','json',$disk->path($result)]);$probe->mustRun();$stream=json_decode($probe->getOutput(),true)['streams'][0];ok($stream['codec_name']==='h264'&&$stream['width']<=640&&$stream['height']<=480,'Output is H.264 at 480p or lower');$bytes=file_get_contents($disk->path($result));ok(strpos($bytes,'moov')<strpos($bytes,'mdat'),'Fast-start metadata precedes video data');ok($disk->exists($source),'Original video retained for existing references');ok(ProductVideos::optimize($result)===$result,'Already optimized product video is not repeatedly re-encoded');
